import json
import pandas as pd

def norm_id(v):
    return int(v)

def norm_str(v):
    if v is None:
        return None
    if isinstance(v, float) and pd.isna(v):
        return None
    s = str(v).strip()
    return s if s != '' else None

def norm_date(v):
    if v is None:
        return None
    if isinstance(v, float) and pd.isna(v):
        return None
    if isinstance(v, str) and v.strip() == '':
        return None
    try:
        return pd.to_datetime(v).strftime('%Y-%m-%d')
    except Exception:
        return str(v)

def norm_status(v):
    if v is None:
        return None
    if isinstance(v, float) and pd.isna(v):
        return None
    if isinstance(v, bool):
        return 'active' if v else 'inactive'
    s = str(v).strip().lower()
    if s in ('true', '1', 'active'):
        return 'active'
    if s in ('false', '0', 'inactive'):
        return 'inactive'
    return str(v).strip()

# ---- Source A (json) ----
with open('/data/source_a/users.json') as f:
    a_list = json.load(f)
a_map = {}
for r in a_list:
    uid = norm_id(r['id'])
    a_map[uid] = {'user_id': uid, 'name': norm_str(r.get('full_name')),
                  'email': norm_str(r.get('email')), 'created_date': norm_date(r.get('registration_date')),
                  'status': norm_status(r.get('status'))}

# ---- Source B (csv) ----
b_df = pd.read_csv('/data/source_b/users.csv')
b_map = {}
for _, row in b_df.iterrows():
    uid = norm_id(row['user_id'])
    b_map[uid] = {'user_id': uid, 'name': norm_str(row.get('name')),
                  'email': norm_str(row.get('email_address')), 'created_date': norm_date(row.get('created_at')),
                  'status': norm_status(row.get('is_active'))}

# ---- Source C (parquet) ----
c_df = pd.read_parquet('/data/source_c/users.parquet')
c_map = {}
for _, row in c_df.iterrows():
    uid = norm_id(row['userId'])
    c_map[uid] = {'user_id': uid, 'name': norm_str(row.get('userName')),
                  'email': norm_str(row.get('email')), 'created_date': norm_date(row.get('joined')),
                  'status': norm_status(row.get('active'))}

sources = {'source_a': a_map, 'source_b': b_map, 'source_c': c_map}
priority = ['source_a', 'source_b', 'source_c']
fields = ['name', 'email', 'created_date', 'status']

all_ids = sorted(set(list(a_map) + list(b_map) + list(c_map)))
conflicts = []
merged_rows = []
for uid in all_ids:
    row = {'user_id': uid}
    for f in fields:
        src_vals = {s: sources[s][uid].get(f) for s in priority if uid in sources[s]}
        selected = None
        for s in priority:
            if s in src_vals and src_vals[s] is not None:
                selected = src_vals[s]
                break
        row[f] = selected
        distinct = set(v for v in src_vals.values() if v is not None)
        if len(distinct) > 1:
            values = {s: src_vals[s] for s in priority if s in src_vals and src_vals[s] is not None}
            conflicts.append({'user_id': uid, 'field': f, 'values': values, 'selected': selected})
    merged_rows.append(row)

merged_df = pd.DataFrame(merged_rows, columns=['user_id', 'name', 'email', 'created_date', 'status'])
merged_df['user_id'] = merged_df['user_id'].astype('int64')
for col in ['name', 'email', 'created_date', 'status']:
    merged_df[col] = merged_df[col].astype('object')
merged_df.to_parquet('/app/merged_users.parquet', index=False)

report = {'total_conflicts': len(conflicts), 'conflicts': conflicts}
with open('/app/conflicts.json', 'w') as f:
    json.dump(report, f, indent=2)

print('=== MERGED (dtypes) ===')
print(merged_df.dtypes)
print(merged_df.to_string())
print('=== CONFLICTS ===')
print(json.dumps(report, indent=2))
PYEOF
